<?php
require_once __DIR__.'/../config/koneksi.php';require_role(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='add'){$kode=strtoupper(trim($_POST['kode_qr']??''));$nama=trim($_POST['nama_ruangan']??'');if($kode&&$nama){$s=$conn->prepare('INSERT INTO ruangan(kode_qr,nama_ruangan) VALUES(?,?)');$s->bind_param('ss',$kode,$nama);$s->execute();}}
 if($action==='delete'){$id=(int)$_POST['id'];$s=$conn->prepare('DELETE FROM ruangan WHERE id=?');$s->bind_param('i',$id);$s->execute();}
 redirect('admin/kelola_ruangan.php');
}
$rooms=$conn->query('SELECT * FROM ruangan ORDER BY id')->fetch_all(MYSQLI_ASSOC);$page_title='Kelola Ruangan';include __DIR__.'/../includes/header.php';
?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 page-heading">Kelola Ruangan</h1><p class="muted">Tambah ruangan dan cetak QR untuk akses formulir.</p></div><a class="btn btn-outline-primary" href="<?= e(base_url('admin/kelola_indikator.php')) ?>">Kelola indikator</a></div>
<div class="card p-3 mb-4"><h2 class="h5">Tambah Ruangan</h2><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add"><div class="col-md-4"><input class="form-control" name="kode_qr" placeholder="Kode QR, mis. GUDANG-01" required></div><div class="col-md-6"><input class="form-control" name="nama_ruangan" placeholder="Nama ruangan" required></div><div class="col-md-2"><button class="btn btn-primary w-100">Tambah</button></div></form></div>
<div class="row g-3"><?php foreach($rooms as $r):$target=base_url('petugas/form_ceklist.php?qr='.rawurlencode($r['kode_qr'])); ?><div class="col-12 col-md-6"><div class="card p-3 h-100"><h2 class="h5"><?= e($r['nama_ruangan']) ?></h2><code><?= e($r['kode_qr']) ?></code><div id="qr<?= (int)$r['id'] ?>" class="my-3"></div><div class="d-flex gap-2"><button class="btn btn-outline-primary btn-sm" onclick="printQr('qr<?= (int)$r['id'] ?>')">Cetak QR</button><a class="btn btn-outline-secondary btn-sm" href="<?= e($target) ?>" target="_blank">Buka formulir</a><form method="post" onsubmit="return confirm('Hapus ruangan ini beserta data terkait?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-outline-danger btn-sm">Hapus</button></form></div></div></div><script>document.addEventListener('DOMContentLoaded',()=>new QRCode(document.getElementById('qr<?= (int)$r['id'] ?>'),{text:<?= json_encode($target) ?>,width:150,height:150}));</script><?php endforeach; ?></div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>function printQr(id){const node=document.getElementById(id),w=window.open('','_blank');w.document.write('<html><body style="font-family:Arial;text-align:center"><h3>'+node.parentElement.querySelector('h2').innerText+'</h3>'+node.innerHTML+'</body></html>');w.document.close();w.print()}</script>
